import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Save and continue later","description":"Let people filling out a form pause and resume it later.","frontmatter":{"title":"Save and continue later","description":"Let people filling out a form pause and resume it later."},"headers":[],"relativePath":"en/formulare/speichern-und-fortsetzen.md","filePath":"en/formulare/speichern-und-fortsetzen.md","lastUpdated":1787319236000}'),o={name:"en/formulare/speichern-und-fortsetzen.md"};function n(s,t,l,d,h,u){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="save-and-continue-later" tabindex="-1">Save and continue later <a class="header-anchor" href="#save-and-continue-later" aria-label="Permalink to &quot;Save and continue later&quot;">​</a></h1><p>This feature lets people filling out a form pause and later pick up exactly where they left off — without losing any input.</p><p>The description in the interface:</p><blockquote><p><strong>Save and continue later</strong></p><p><em>Respondents can come back later, pick up where they left off, and complete the form without their previously entered data being lost.</em></p></blockquote><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>In the <strong>More</strong> tab of the form editor: <strong>Save to continue later</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Plan-dependent</p><p>This feature isn&#39;t available on the entry-level plan.</p></div><h2 id="what-people-filling-it-out-see" tabindex="-1">What people filling it out see <a class="header-anchor" href="#what-people-filling-it-out-see" aria-label="Permalink to &quot;What people filling it out see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Save button</td><td><strong>Continue later</strong></td></tr><tr><td>Confirmation</td><td><em>Form has been saved!</em></td></tr><tr><td>On returning</td><td><em>This form has been saved but not yet submitted!</em></td></tr><tr><td>Explanation</td><td><em>You can finish filling out the form later.</em></td></tr><tr><td>Discard saved state</td><td><strong>Delete all</strong></td></tr><tr><td>Close dialog</td><td><strong>Done</strong></td></tr></tbody></table><h2 id="why-it-s-worth-it" tabindex="-1">Why it&#39;s worth it <a class="header-anchor" href="#why-it-s-worth-it" aria-label="Permalink to &quot;Why it&#39;s worth it&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Without this feature, input is lost</p><p>A form is only saved <strong>when submitted</strong>. If someone closes the browser on page 3 of 5, everything is gone — without warning.</p><p>For anything that takes more than a few minutes, this feature isn&#39;t a convenience — it&#39;s protection against frustration and abandonment.</p></div><p>Especially worthwhile for:</p><ul><li><a href="/en/formulare/mehrseitige-formulare">multi-page forms</a></li><li>forms with many fields</li><li>forms that require gathering documents</li><li>forms mostly filled out on mobile</li></ul><h2 id="important-characteristics" tabindex="-1">Important characteristics <a class="header-anchor" href="#important-characteristics" aria-label="Permalink to &quot;Important characteristics&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">A saved state is not yet an entry</p><p>Until it&#39;s submitted, <strong>no entry exists on the Grid</strong>. The data is stored temporarily and isn&#39;t visible to you.</p><p>A Flow with the trigger <em>Entry via form</em> only starts when the form is actually submitted.</p></div><div class="warning custom-block"><p class="custom-block-title">The saved state is tied to the device and browser</p><p>Someone who saves on their phone won&#39;t automatically find that state again on their computer. Mention this in the form description if it&#39;s relevant to your case.</p></div><h2 id="distinguishing-it-from-similar-features" tabindex="-1">Distinguishing it from similar features <a class="header-anchor" href="#distinguishing-it-from-similar-features" aria-label="Permalink to &quot;Distinguishing it from similar features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Save to continue later</strong></td><td>The person filling it out pauses and resumes on their own</td></tr><tr><td><a href="/en/formulare/vorausgefuellte-links">Prefilled link</a></td><td><strong>You</strong> preset values before someone fills the form out</td></tr><tr><td><a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></td><td>An <strong>existing</strong> entry gets changed</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Use the other approach for feedback loops</p><p>If you want someone to add to a process later while you can see the state in the meantime, <em>Save</em> is the wrong tool — the data is invisible to you until submission.</p><p>Instead, have the entry created immediately and send a prefilled form link via a <a href="/en/flows/aktionen">Flow</a> for follow-up.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/mehrseitige-formulare">Multi-page forms</a></li><li><a href="/en/formulare/vorausgefuellte-links">Prefilled links</a></li><li><a href="/en/formulare/formular-erstellen">Creating a form</a></li></ul>',21)])])}const f=e(o,[["render",n]]);export{c as __pageData,f as default};
